import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const p=JSON.parse('{"title":"小過","description":"焦氏易林注 - 小過","frontmatter":{"title":"小過","description":"焦氏易林注 - 小過"},"headers":[],"relativePath":"zh/classics/jiaoyilin/062.md","filePath":"zh/classics/jiaoyilin/062.md"}'),l={name:"zh/classics/jiaoyilin/062.md"};function n(d,a,t,s,o,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="小過" tabindex="-1">小過 <a class="header-anchor" href="#小過" aria-label="Permalink to “小過”">​</a></h1><h3 id="小過-1" tabindex="-1">小過 <a class="header-anchor" href="#小過-1" aria-label="Permalink to “小過”">​</a></h3><h3 id="小過之乾" tabindex="-1">小過之乾 <a class="header-anchor" href="#小過之乾" aria-label="Permalink to “小過之乾”">​</a></h3><h3 id="林辞" tabindex="-1">林辞 <a class="header-anchor" href="#林辞" aria-label="Permalink to “林辞”">​</a></h3><p>積德累仁，靈佑順信，福祉日增。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>乾為仁德、為信、為福，順行純乾，故曰積、曰累。</p><h3 id="小過之坤" tabindex="-1">小過之坤 <a class="header-anchor" href="#小過之坤" aria-label="Permalink to “小過之坤”">​</a></h3><h3 id="林辞-1" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-1" aria-label="Permalink to “林辞”">​</a></h3><p>謹慎重言，不幸遭患。周召述職，脫免牢門。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>此用《小過》象。艮為謹慎，震為言，正反震故曰重言。互大坎為患。震為周、為召，坎為牢獄，艮為門，震出在外，故曰脫免。○門，宋元本作開，依汲古。</p><h3 id="小過之屯" tabindex="-1">小過之屯 <a class="header-anchor" href="#小過之屯" aria-label="Permalink to “小過之屯”">​</a></h3><h3 id="林辞-2" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-2" aria-label="Permalink to “林辞”">​</a></h3><p>鳥飛鼓翼，喜樂堯德。虞夏美功，要荒賓服。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>艮為鳥，震為翼、為鼓、為飛、為帝，故曰堯，故曰虞夏。坤為要荒。</p><h3 id="小過之蒙" tabindex="-1">小過之蒙 <a class="header-anchor" href="#小過之蒙" aria-label="Permalink to “小過之蒙”">​</a></h3><h3 id="林辞-3" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-3" aria-label="Permalink to “林辞”">​</a></h3><p>牙孽生齒，室堂啟戶。幽人利貞，鼓翼起舞。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>詳《臨》之《姤》。</p><h3 id="小過之需" tabindex="-1">小過之需 <a class="header-anchor" href="#小過之需" aria-label="Permalink to “小過之需”">​</a></h3><h3 id="林辞-4" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-4" aria-label="Permalink to “林辞”">​</a></h3><p>使伯採桑，拒不肯行。與叔爭訟，更相毀傷。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>依《離》之《明夷》校。採桑，各本皆訛東求。</p><h3 id="小過之訟" tabindex="-1">小過之訟 <a class="header-anchor" href="#小過之訟" aria-label="Permalink to “小過之訟”">​</a></h3><h3 id="林辞-5" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-5" aria-label="Permalink to “林辞”">​</a></h3><p>手足易處，頭尾顛倒。公為雌嫗，亂其蠶織。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>詳《夬》之《蹇》。惟此用《小過》象。艮為手，在下，震為足，在上，故曰易處。艮為頭，在下，覆艮為尾，在上，故曰顛倒。震為公，與兌連體，故曰公為雌嫗。巽為蠶、為織，巽隕，故曰亂。</p><h3 id="小過之師" tabindex="-1">小過之師 <a class="header-anchor" href="#小過之師" aria-label="Permalink to “小過之師”">​</a></h3><h3 id="林辞-6" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-6" aria-label="Permalink to “林辞”">​</a></h3><p>匠卿操斧，豫章危殆。袍衣脫剝，祿命訖已。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>劉毓松雲《左傳襄四年》匠慶用蒲圍之檟，慶卿古通用。匠卿即匠慶，魯匠人也。伏巽為工，故曰匠卿。震為木，故曰豫章。坎為危殆，震為袍衣。伏巽為命，坤喪，故曰訖已。訖，終也。○卿，或為慶之音訛字。豫章，大木也。</p><h3 id="小過之比" tabindex="-1">小過之比 <a class="header-anchor" href="#小過之比" aria-label="Permalink to “小過之比”">​</a></h3><h3 id="林辞-7" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-7" aria-label="Permalink to “林辞”">​</a></h3><p>天女踞床，不成文章。南箕無舌，飯多沙糠。虐眾盜名，雌雄折頸。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>詳《大畜》之《益》。糠，元本訛糖，依汲古。</p><h3 id="小過之小畜" tabindex="-1">小過之小畜 <a class="header-anchor" href="#小過之小畜" aria-label="Permalink to “小過之小畜”">​</a></h3><h3 id="林辞-8" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-8" aria-label="Permalink to “林辞”">​</a></h3><p>大椎破轂，長舌亂國。牆茨之言，三世不安。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>艮為椎，震為轂，兌毀，故曰破轂。兌為舌，震為大兌，故曰長舌。巽為牆，坎為茨，《毛傳》茨，蒺藜也。震為言，數三，艮為世，故曰三世。</p><h3 id="小過之履" tabindex="-1">小過之履 <a class="header-anchor" href="#小過之履" aria-label="Permalink to “小過之履”">​</a></h3><h3 id="林辞-9" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-9" aria-label="Permalink to “林辞”">​</a></h3><p>銜命辱使，不堪厥事。中墮落去，更為斯吏。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>巽為兌口，巽為命，故曰銜命。巽為隕落，故曰中墮落去。伏艮為僮僕，故曰斯吏。《後漢左雄傳》職斯祿薄，註：斯，賤也。○墮，各本皆作墜，斯吏作負載，茲依《未濟》之《坎》校。</p><h3 id="小過之泰" tabindex="-1">小過之泰 <a class="header-anchor" href="#小過之泰" aria-label="Permalink to “小過之泰”">​</a></h3><h3 id="林辞-10" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-10" aria-label="Permalink to “林辞”">​</a></h3><p>三蛇共室，同類相得。甘露時降，生我百谷。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>伏巽為蛇，艮為室，數三，故曰三蛇共室。兌為露，震為生、為百谷。</p><h3 id="小過之否" tabindex="-1">小過之否 <a class="header-anchor" href="#小過之否" aria-label="Permalink to “小過之否”">​</a></h3><h3 id="林辞-11" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-11" aria-label="Permalink to “林辞”">​</a></h3><p>衣宵夜游，與君相逢。除患解惑，使我不憂。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>詳《歸妹》之《大有》。衣宵，原作衣繡，遭作逢，《歸妹》之《大有》、《旅》之《小過》繡皆作宵。按：《禮記》鄭註：宵，即繒也，與繡義略同，茲作繡，似宵之音訛字，以焦用禮記字此不應獨否，又逢字上下不協，皆依《歸妹》之《大有》校。</p><h3 id="小過之同人" tabindex="-1">小過之同人 <a class="header-anchor" href="#小過之同人" aria-label="Permalink to “小過之同人”">​</a></h3><h3 id="林辞-12" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-12" aria-label="Permalink to “林辞”">​</a></h3><p>被髪獸心，難與為鄰。來如風雲，去如絕弦，為狼所殘。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>此用《小過》象。震為髪，艮為獸，互大坎為心，故曰獸心。巽為風，坎為雲，故曰來如風雲。巽為弦，兌為絕，艮為狼，兌口，故曰為狼所殘。○雲，汲古作雨，依宋元本。</p><h3 id="小過之大有" tabindex="-1">小過之大有 <a class="header-anchor" href="#小過之大有" aria-label="Permalink to “小過之大有”">​</a></h3><h3 id="林辞-13" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-13" aria-label="Permalink to “林辞”">​</a></h3><p>剛柔相呼，二姓為家。霜降既同，惠我以仁。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>詳《家人》之《損》。</p><h3 id="小過之謙" tabindex="-1">小過之謙 <a class="header-anchor" href="#小過之謙" aria-label="Permalink to “小過之謙”">​</a></h3><h3 id="林辞-14" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-14" aria-label="Permalink to “林辞”">​</a></h3><p>牛馬聾瞶，不曉齊味。委以鼎俎，治亂憒憒。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>馬，依《頤》之《鼎》校，各本皆作耳。</p><h3 id="小過之豫" tabindex="-1">小過之豫 <a class="header-anchor" href="#小過之豫" aria-label="Permalink to “小過之豫”">​</a></h3><h3 id="林辞-15" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-15" aria-label="Permalink to “林辞”">​</a></h3><p>低頭竊視，有所畏避。行作不利，酒酢魚喂，眾莫貪嗜。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>詳《鼎》之《解》。作，汲古作旅，酢作酸，依宋元本。</p><h3 id="小過之隨" tabindex="-1">小過之隨 <a class="header-anchor" href="#小過之隨" aria-label="Permalink to “小過之隨”">​</a></h3><h3 id="林辞-16" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-16" aria-label="Permalink to “林辞”">​</a></h3><p>兩師娶婦，黃岩季子。成禮既婚，相呼南去。膏澤下土，年歲大有。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>詳《否》之《坤》。○去，汲古作上，依宋元本。</p><h3 id="小過之蠱" tabindex="-1">小過之蠱 <a class="header-anchor" href="#小過之蠱" aria-label="Permalink to “小過之蠱”">​</a></h3><h3 id="林辞-17" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-17" aria-label="Permalink to “林辞”">​</a></h3><p>戴盆望天，不見星辰。願小失大，遁逃牆外。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>詳《賁》之《蒙》。</p><h3 id="小過之臨" tabindex="-1">小過之臨 <a class="header-anchor" href="#小過之臨" aria-label="Permalink to “小過之臨”">​</a></h3><h3 id="林辞-18" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-18" aria-label="Permalink to “林辞”">​</a></h3><p>二人輦車，徙去其家。井沸釜鳴，不可以居。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>兌卦數二，震為人、為車、為行，故曰徙。伏艮為家，兌為井，坤水在上，故曰井沸。坤為釜，震為鳴，故曰釜鳴。艮為居，艮伏，故曰不可居。</p><h3 id="小過之觀" tabindex="-1">小過之觀 <a class="header-anchor" href="#小過之觀" aria-label="Permalink to “小過之觀”">​</a></h3><h3 id="林辞-19" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-19" aria-label="Permalink to “林辞”">​</a></h3><p>壞臂反肘，怒不可止。狼戻腹心，無與為市。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>艮為臂、為肘，伏震為歸，故曰反肘。震為怒，艮為狼，坤為腹心，巽為市。○止，宋元本作二，狼訛佷，與作以，俱依汲古。狼戻腹心者，言心懷毒佷叵測也。</p><h3 id="小過之噬嗑" tabindex="-1">小過之噬嗑 <a class="header-anchor" href="#小過之噬嗑" aria-label="Permalink to “小過之噬嗑”">​</a></h3><h3 id="林辞-20" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-20" aria-label="Permalink to “林辞”">​</a></h3><p>湯火之憂，轉解喜來。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>離火，坎水，故曰湯火。震為解、為喜，言由坎憂轉為震喜也。○火，宋元本作世，依汲古。</p><h3 id="小過之賁" tabindex="-1">小過之賁 <a class="header-anchor" href="#小過之賁" aria-label="Permalink to “小過之賁”">​</a></h3><h3 id="林辞-21" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-21" aria-label="Permalink to “林辞”">​</a></h3><p>忠信輔成，王政不傾。公劉肇基，文武綏之。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>坎為忠信，震為王，艮成終，故曰成王，言周公輔佐成王也。震為公，艮為基，離為文，震為武，故曰文武綏之。○基，宋元本作舉，依汲古。</p><h3 id="小過之剝" tabindex="-1">小過之剝 <a class="header-anchor" href="#小過之剝" aria-label="Permalink to “小過之剝”">​</a></h3><h3 id="林辞-22" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-22" aria-label="Permalink to “林辞”">​</a></h3><p>登高斬木，頓躓蹈險。車傾馬罷，伯叔吁嗟。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>一陽在上，故曰登高。艮為木、為刀劍，故曰斬木。震為車，震覆，故曰車傾。坤為馬、為勞，故曰馬罷。罷疲同，音婆，與蹉韻。○罷，汲古作疲，依宋元本。第四句汲古作叔伯蹉噓，乃後人所改，以與疲葉，豈知疲音皮，皮音婆，古經傳罷倦之罷固皆讀婆也。凡易林罷字無不協婆，以此見易林用字之古，與經傳同，《易中孚六三》罷與歌韻是其證也。</p><h3 id="小過之復" tabindex="-1">小過之復 <a class="header-anchor" href="#小過之復" aria-label="Permalink to “小過之復”">​</a></h3><h3 id="林辞-23" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-23" aria-label="Permalink to “林辞”">​</a></h3><p>桑之將落，隕其黃葉。失勢傾側，而無所立。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>首二句宋本作桑之隕落、黃敗其葉，元本作桑之落隕，次句同宋，汲古作桑方隕落、黃葉敗散，茲依《履》之《噬嗑》校。</p><h3 id="小過之無妄" tabindex="-1">小過之無妄 <a class="header-anchor" href="#小過之無妄" aria-label="Permalink to “小過之無妄”">​</a></h3><h3 id="林辞-24" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-24" aria-label="Permalink to “林辞”">​</a></h3><p>鸞鳳翱翔，集於家國。念我伯姊，與母相得。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>伏坤為文，艮鳥，故曰鸞鳳。艮為家國，巽長女，故曰伯姊。伏坤為母。○家，宋元本作喜，依汲古。惟汲古作國家，非，依宋元本。</p><h3 id="小過之大畜" tabindex="-1">小過之大畜 <a class="header-anchor" href="#小過之大畜" aria-label="Permalink to “小過之大畜”">​</a></h3><h3 id="林辞-25" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-25" aria-label="Permalink to “林辞”">​</a></h3><p>陰淫所居，盈溢過度，傷害禾稼。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>通《萃》。坤為陰、為水，兌澤亦為水，故曰陰淫、曰盈溢。巽為禾稼，兌毀，故曰傷害禾稼。○盈，宋元本作益，非，依汲古。</p><h3 id="小過之頤" tabindex="-1">小過之頤 <a class="header-anchor" href="#小過之頤" aria-label="Permalink to “小過之頤”">​</a></h3><h3 id="林辞-26" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-26" aria-label="Permalink to “林辞”">​</a></h3><p>霄冥高山，道險峻難。王孫罷極，困於阪間。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>艮為天，故曰霄。《玉篇》霄，雲氣也。霄冥高山，言山高入霄漢青冥之間也。震為王，艮為孫，坤為勞，故曰罷極。艮為道、為阪，坤為困苦，正反艮，故曰困於阪間。</p><h3 id="小過之大過" tabindex="-1">小過之大過 <a class="header-anchor" href="#小過之大過" aria-label="Permalink to “小過之大過”">​</a></h3><h3 id="林辞-27" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-27" aria-label="Permalink to “林辞”">​</a></h3><p>和璧隋珠，為火所燒。冥昧失明，奪精無光，棄於道旁。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>通《頤》。震為珠、為玉，艮為火，故曰為火所燒。坤為黑，故曰冥昧失明、曰奪精無光。震為精，艮為光、為道。○奪，宋本訛奮，依元本、汲古。於，元本作其，依宋本、汲古。</p><h3 id="小過之坎" tabindex="-1">小過之坎 <a class="header-anchor" href="#小過之坎" aria-label="Permalink to “小過之坎”">​</a></h3><h3 id="林辞-28" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-28" aria-label="Permalink to “林辞”">​</a></h3><p>虞君好神，惠我老親。恭承宗廟，雖慍不去，復我內室。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>《左傳僖五年》虞公曰：吾享祀豐潔，神必據我，故曰好神。互震為神。艮為宗廟，坎為慍。○神，汲古作田，非，依宋元本。惠，元本作惡，依宋本、汲古。雖，汲古作長，依宋元本。</p><h3 id="小過之離" tabindex="-1">小過之離 <a class="header-anchor" href="#小過之離" aria-label="Permalink to “小過之離”">​</a></h3><h3 id="林辞-29" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-29" aria-label="Permalink to “林辞”">​</a></h3><p>爪牙之士，怨毒祈父。轉憂與己，傷不及母。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>詳《謙》之《歸妹》。士，宋元本作夫，依汲古。祈，元本作圻，依宋本、汲古。</p><h3 id="小過之咸" tabindex="-1">小過之咸 <a class="header-anchor" href="#小過之咸" aria-label="Permalink to “小過之咸”">​</a></h3><h3 id="林辞-30" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-30" aria-label="Permalink to “林辞”">​</a></h3><p>倉盈庾億，宜稼黍稷，年歲有息。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>詳《乾》之《師》。</p><h3 id="小過之恒" tabindex="-1">小過之恒 <a class="header-anchor" href="#小過之恒" aria-label="Permalink to “小過之恒”">​</a></h3><h3 id="林辞-31" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-31" aria-label="Permalink to “林辞”">​</a></h3><p>窗牖戶房，通利明光。賢智輔聖，仁德大行。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>家給人足，海內殷昌。詳《大畜》之《升》。房，汲古訛傍。</p><h3 id="小過之遯" tabindex="-1">小過之遯 <a class="header-anchor" href="#小過之遯" aria-label="Permalink to “小過之遯”">​</a></h3><h3 id="林辞-32" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-32" aria-label="Permalink to “林辞”">​</a></h3><p>切切之患，凶重憂薦，為虎所吞。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>伏坤為憂患、為凶，艮為虎，伏兌口，故曰為虎所吞。○切切，汲古作忉忉，依汲古。</p><h3 id="小過之大壯" tabindex="-1">小過之大壯 <a class="header-anchor" href="#小過之大壯" aria-label="Permalink to “小過之大壯”">​</a></h3><h3 id="林辞-33" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-33" aria-label="Permalink to “林辞”">​</a></h3><p>水無魚滋，陸為海涯。君子失居，小人相攜。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>坤為水、為魚，坤伏，故曰水無魚滋。滋，生也。伏艮為陸，坤為海，艮坤相連，故曰陸為海涯。艮為君子、為居，巽隕落，故失居。坤為小人，重坤，故曰相攜。○滋，宋元本作池，依汲古。</p><h3 id="小過之晉" tabindex="-1">小過之晉 <a class="header-anchor" href="#小過之晉" aria-label="Permalink to “小過之晉”">​</a></h3><h3 id="林辞-34" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-34" aria-label="Permalink to “林辞”">​</a></h3><p>九疑鬱林，沮濕不中。鸞鳳所惡，君子攸去。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>詳《無妄》之《巽》。</p><h3 id="小過之明夷" tabindex="-1">小過之明夷 <a class="header-anchor" href="#小過之明夷" aria-label="Permalink to “小過之明夷”">​</a></h3><h3 id="林辞-35" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-35" aria-label="Permalink to “林辞”">​</a></h3><p>六翮泛飛，走歸不及。脫歸王室，亡其騂特。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>震為翮、為飛，坎數六，故曰六翮泛飛。震為走、為歸，坎陷，故不及。震為王，坎為室、為馬，坎為赤，故曰騂。騂，赤色馬也。坤為牛，故曰特。坤喪，故曰亡其騂特。○泛，宋元本作況，依汲古。</p><h3 id="小過之家人" tabindex="-1">小過之家人 <a class="header-anchor" href="#小過之家人" aria-label="Permalink to “小過之家人”">​</a></h3><h3 id="林辞-36" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-36" aria-label="Permalink to “林辞”">​</a></h3><p>不直莊公，與我爭訟。媒伯無禮，自令壅塞。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>詳前。莊，前作杜，莫知孰是，姑兩存之。</p><h3 id="小過之睽" tabindex="-1">小過之睽 <a class="header-anchor" href="#小過之睽" aria-label="Permalink to “小過之睽”">​</a></h3><h3 id="林辞-37" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-37" aria-label="Permalink to “林辞”">​</a></h3><p>瘡痍多病，宋公危殘。吳子巢門，殞命失所。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>詳《兌》之《蠱》。瘡痍多病，元本、汲古作倉庚多億，依宋本。</p><h3 id="小過之蹇" tabindex="-1">小過之蹇 <a class="header-anchor" href="#小過之蹇" aria-label="Permalink to “小過之蹇”">​</a></h3><h3 id="林辞-38" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-38" aria-label="Permalink to “林辞”">​</a></h3><p>失羊捕牛，無損無憂。兌為羊，兌伏，故曰失羊。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>艮為牛，艮手，故曰捕牛。</p><h3 id="小過之解" tabindex="-1">小過之解 <a class="header-anchor" href="#小過之解" aria-label="Permalink to “小過之解”">​</a></h3><h3 id="林辞-39" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-39" aria-label="Permalink to “林辞”">​</a></h3><p>夏麥麩，霜擊其芒。疾君敗國，使我誅傷。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>詳《泰》之《賁》。麩，依宋元本，汲古作麩，非。</p><h3 id="小過之損" tabindex="-1">小過之損 <a class="header-anchor" href="#小過之損" aria-label="Permalink to “小過之損”">​</a></h3><h3 id="林辞-40" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-40" aria-label="Permalink to “林辞”">​</a></h3><p>昧昧暗暗，不知白黑。風雨亂擾，光明伏匿，幽王失國。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>坤黑，故曰昧暗。巽為白，巽伏，故不知。坤為風、為亂，兌為雨，故曰風雨亂擾。艮為光明，坤閉，故伏匿。震為王，坤黑，故曰幽王。坤為國、為喪，故曰失國。</p><h3 id="小過之益" tabindex="-1">小過之益 <a class="header-anchor" href="#小過之益" aria-label="Permalink to “小過之益”">​</a></h3><h3 id="林辞-41" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-41" aria-label="Permalink to “林辞”">​</a></h3><p>執斧破薪，使媒求婦。和合二姓，親御飲酒。色比毛嬙，姑公悅喜。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>詳《家人》之《漸》。毛嬙，古美女名。第四句宋元本作親迎斯須，非，依汲古。</p><h3 id="小過之夬" tabindex="-1">小過之夬 <a class="header-anchor" href="#小過之夬" aria-label="Permalink to “小過之夬”">​</a></h3><h3 id="林辞-42" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-42" aria-label="Permalink to “林辞”">​</a></h3><p>六疾生狂，痴走妄行。北入患門，與禍為鄰。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>伏坤為疾，乾數六，故曰六疾。兌剛魯，故曰狂、曰妄、曰痴。乾為行，坤為禍患、為門，位北，故曰北入患門。○第二句元本作妄痴走行，依宋本、汲古。</p><h3 id="小過之姤" tabindex="-1">小過之姤 <a class="header-anchor" href="#小過之姤" aria-label="Permalink to “小過之姤”">​</a></h3><h3 id="林辞-43" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-43" aria-label="Permalink to “林辞”">​</a></h3><p>驅羊就群，佷不肯前。慶季愎諫，子之被患。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>通《復》。震為羊，坤為群，坤閉，故不前。震為諫，坤為患。《左傳襄二十八年》慶嗣謂慶封曰：禍將作矣，請速歸，慶封不聽。又其女盧蒲薑曰：夫子愎，莫之止，將不出。子之，即慶舍，為慶封子。慶季，即慶封。後子之被盧蒲癸刺死，慶封奔魯。○佷，汲古作狼，依宋元本。</p><h3 id="小過之萃" tabindex="-1">小過之萃 <a class="header-anchor" href="#小過之萃" aria-label="Permalink to “小過之萃”">​</a></h3><h3 id="林辞-44" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-44" aria-label="Permalink to “林辞”">​</a></h3><p>二人共路，東趨西步。十里之外，不相知處。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>共，依《比》之《損》校，各本皆作異，非。</p><h3 id="小過之升" tabindex="-1">小過之升 <a class="header-anchor" href="#小過之升" aria-label="Permalink to “小過之升”">​</a></h3><h3 id="林辞-45" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-45" aria-label="Permalink to “林辞”">​</a></h3><p>義不勝情，以欲自營。幾利危躬，折角摧頸。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>詳前。危，汲古訛為，依宋元本。幾皆作睹，依《坤》之《豐》校。</p><h3 id="小過之困" tabindex="-1">小過之困 <a class="header-anchor" href="#小過之困" aria-label="Permalink to “小過之困”">​</a></h3><h3 id="林辞-46" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-46" aria-label="Permalink to “林辞”">​</a></h3><p>騷騷擾擾，不安其類。疾在頸項，凶危為憂。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>巽進退不果，故曰騷擾、曰不安。坎為疾，艮為項頸，艮伏，兌見，兌毀在上，故曰疾在頭頸。坎為危憂。</p><h3 id="小過之井" tabindex="-1">小過之井 <a class="header-anchor" href="#小過之井" aria-label="Permalink to “小過之井”">​</a></h3><h3 id="林辞-47" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-47" aria-label="Permalink to “林辞”">​</a></h3><p>三河俱合，水怒涌躍。壞我王室，民困於食。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>詳《蠱》之《頤》。</p><h3 id="小過之革" tabindex="-1">小過之革 <a class="header-anchor" href="#小過之革" aria-label="Permalink to “小過之革”">​</a></h3><h3 id="林辞-48" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-48" aria-label="Permalink to “林辞”">​</a></h3><p>陽曜旱疾，傷病稼穡，農人無食。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>離火，故曰陽曜、曰旱。伏坎為疾病，巽為稼牆，伏震為耕，故曰農人。坤虛，故無食。</p><h3 id="小過之鼎" tabindex="-1">小過之鼎 <a class="header-anchor" href="#小過之鼎" aria-label="Permalink to “小過之鼎”">​</a></h3><h3 id="林辞-49" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-49" aria-label="Permalink to “林辞”">​</a></h3><p>流浮出食，載豢入屋。釋轡系馬，西南廡下。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>通《屯》。坎水，坤水，故曰流浮。震為出、為食，坤為載豢，《說文》以谷圈養豕也。坎為豕，故曰載豢入屋。艮為屋，震為馬、為釋，巽為轡、為系，故曰釋轡系馬。坤為西南、為下，上艮，故曰廡下。○轡，宋元本作鞍，依汲古。</p><h3 id="小過之震" tabindex="-1">小過之震 <a class="header-anchor" href="#小過之震" aria-label="Permalink to “小過之震”">​</a></h3><h3 id="林辞-50" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-50" aria-label="Permalink to “林辞”">​</a></h3><p>門戶之居，可以止舍。進仕不殆，安樂相保。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>互艮為門戶、為居，艮止，故曰舍。艮為官，故曰仕。震為進、為樂，坎為殆，震解，故不殆。○仕，汲古訛士，依宋元本。</p><h3 id="小過之艮" tabindex="-1">小過之艮 <a class="header-anchor" href="#小過之艮" aria-label="Permalink to “小過之艮”">​</a></h3><h3 id="林辞-51" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-51" aria-label="Permalink to “林辞”">​</a></h3><p>過時不歸，雌雄苦悲。徘徊外國，與母分離。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>詳《豫》之《大壯》。</p><h3 id="小過之漸" tabindex="-1">小過之漸 <a class="header-anchor" href="#小過之漸" aria-label="Permalink to “小過之漸”">​</a></h3><h3 id="林辞-52" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-52" aria-label="Permalink to “林辞”">​</a></h3><p>中田有廬，疆埸有瓜。獻進皇祖，曾孫壽考。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>坎為中，艮為田、為廬、為疆埸、為瓜，艮為壽、為祖，又為曾孫。林詞皆小雅詩句。</p><h3 id="小過之歸妹" tabindex="-1">小過之歸妹 <a class="header-anchor" href="#小過之歸妹" aria-label="Permalink to “小過之歸妹”">​</a></h3><h3 id="林辞-53" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-53" aria-label="Permalink to “林辞”">​</a></h3><p>失時無友，覆家出走，傫如喪狗。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>艮為時、為友、為家，艮覆，故曰失時、曰無友、曰覆家。震為出走，艮為狗，艮覆，故曰喪狗。全取反艮象。《家語》孔子在衛東門外，傫傫如喪家之狗。○傫，汲古作何，依宋元本。</p><h3 id="小過之豐" tabindex="-1">小過之豐 <a class="header-anchor" href="#小過之豐" aria-label="Permalink to “小過之豐”">​</a></h3><h3 id="林辞-54" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-54" aria-label="Permalink to “林辞”">​</a></h3><p>反鼻歧頭，二寡獨居。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>艮為鼻，上卦艮反，故曰反鼻。《釋名》物兩為歧，艮為頭，艮反向上，故象形曰歧頭。巽為寡，二至五正反巽，又兌卦數二，故曰二寡。○二，宋元本作三，依汲古。</p><h3 id="小過之旅" tabindex="-1">小過之旅 <a class="header-anchor" href="#小過之旅" aria-label="Permalink to “小過之旅”">​</a></h3><h3 id="林辞-55" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-55" aria-label="Permalink to “林辞”">​</a></h3><p>衣裳顛倒，為王來呼。成就東周，封受大福。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>通《節》。震為衣裳，正反震，故曰衣裳顛倒。震為王，兌為呼，《詩齊風》顛倒衣裳，自公召之。震為東、為周，艮為成，故曰成就東周。震為福，義與毛異。</p><h3 id="小過之巽" tabindex="-1">小過之巽 <a class="header-anchor" href="#小過之巽" aria-label="Permalink to “小過之巽”">​</a></h3><h3 id="林辞-56" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-56" aria-label="Permalink to “林辞”">​</a></h3><p>飛不遠去，還歸故處，興事多悔。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>巽進退不果，故曰飛不遠去、還歸故處。伏震為飛、為反，故曰還歸。</p><h3 id="小過之兌" tabindex="-1">小過之兌 <a class="header-anchor" href="#小過之兌" aria-label="Permalink to “小過之兌”">​</a></h3><h3 id="林辞-57" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-57" aria-label="Permalink to “林辞”">​</a></h3><p>含血走禽，不曉五音。瓠巴鼓瑟，不悅於心。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>瓠巴，人名。《荀子》瓠巴鼓瑟，游魚出聽；《列子》瓠巴鼓瑟，而鳥舞魚躍。首二句言鳥獸含有氣血，並不曉音律，然一聞瓠巴鼓瑟而感於心也。伏坎為血，艮為禽。伏震為音，巽卦數五，故曰五音。艮為瓠，震為鼓、為瑟。坎為心，坎憂，故不悅。○瓠，汲古訛匏，依宋元本。</p><h3 id="小過之渙" tabindex="-1">小過之渙 <a class="header-anchor" href="#小過之渙" aria-label="Permalink to “小過之渙”">​</a></h3><h3 id="林辞-58" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-58" aria-label="Permalink to “林辞”">​</a></h3><p>求玉獲石，非心所欲，祝願不得。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>震為玉，艮為求、為石，故曰求玉獲石。坎為心愿，坎失，巽隕，故不得。</p><h3 id="小過之節" tabindex="-1">小過之節 <a class="header-anchor" href="#小過之節" aria-label="Permalink to “小過之節”">​</a></h3><h3 id="林辞-59" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-59" aria-label="Permalink to “林辞”">​</a></h3><p>山崩谷絕，大福盡竭。涇渭失紀，玉厯既已。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>厯，各本皆作石，依《屯》之《蒙》校。既，盡也。</p><h3 id="小過之中孚" tabindex="-1">小過之中孚 <a class="header-anchor" href="#小過之中孚" aria-label="Permalink to “小過之中孚”">​</a></h3><h3 id="林辞-60" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-60" aria-label="Permalink to “林辞”">​</a></h3><p>嗔目懼怒，不安其居。散渙府藏，無有利得。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>震為怒，互大離，故曰瞋目懼怒。艮為居、為安，風隕落，故不安其居。艮為府，巽為散渙、為利。此指呂嬃散棄財實事。</p><h3 id="小過之小過" tabindex="-1">小過之小過 <a class="header-anchor" href="#小過之小過" aria-label="Permalink to “小過之小過”">​</a></h3><h3 id="林辞-61" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-61" aria-label="Permalink to “林辞”">​</a></h3><p>初雖驚惶，後乃無傷。受其福慶，永永其祥。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>震為驚、為後、為福慶。</p><h3 id="小過之既濟" tabindex="-1">小過之既濟 <a class="header-anchor" href="#小過之既濟" aria-label="Permalink to “小過之既濟”">​</a></h3><h3 id="林辞-62" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-62" aria-label="Permalink to “林辞”">​</a></h3><p>眾邪充側，鳳凰折翼。微子復北，去其邦國。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>多用半象。</p><h3 id="小過之未濟" tabindex="-1">小過之未濟 <a class="header-anchor" href="#小過之未濟" aria-label="Permalink to “小過之未濟”">​</a></h3><h3 id="林辞-63" tabindex="-1">林辞 <a class="header-anchor" href="#林辞-63" aria-label="Permalink to “林辞”">​</a></h3><p>六月採，征伐無道。張仲方叔，克敵飲酒。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>詳《離》之《坎》。○方叔克敵，汲古作叔季孝友，依宋元本。</p>',322)])])}const m=e(l,[["render",n]]);export{p as __pageData,m as default};
